export interface InspectionType {
  /**
   * @displayName Inspection Type ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Inspection Type Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  inspectionTypeName: string;
  /**
   * @displayName Active
   * @validationRule Required for create/update operations
   */
  active: boolean;
  /**
   * @displayName Display Order
   * @validationRule Required for create/update operations
   */
  displayOrder: number;
  /**
   * @displayName Repeatable
   * @validationRule Required for create/update operations
   */
  repeatable: boolean;
  /**
   * @displayName Source Form
   * @validationRule Required for create/update operations
   */
  sourceForm: string;
}

export const _InspectionType = 'InspectionType' as const;